#!/usr/bin/env bash
# Cut a release: sign, build, hash, and write the manifest the updater reads.
#
# One command, because the alternative is a checklist that gets half-followed
# and produces an artifact nobody can install over the last one. Every step
# below exists because skipping it fails silently rather than loudly:
#
#   · the version lives in `pubspec.yaml` and nowhere else, but Gradle reads
#     `android/local.properties` — that file is generated by `flutter build apk`
#     and this script does not call it (see tool/build_apk.sh for why it cannot),
#     so the version is written into local.properties here or the APK ships
#     stamped 0.1.0 forever;
#   · the Dart side needs the same number through `--dart-define`, because the
#     build must know its own version before any platform channel answers;
#   · the SHA-256 is computed from the bytes that were actually signed and copied,
#     not from a rebuild;
#   · `update.json` must be written *after* the hash, never before.
#
# What this script does NOT do: talk to GitHub. It leaves `dist/update.json` and
# the APK, and prints the `gh release create` line that uploads them. Keeping the
# network out of here means the whole thing can be re-run offline and compared,
# and that a half-finished upload cannot look like a half-finished build.
#
# Usage:
#
#   tool/release.sh                          # build + manifest for the current version
#   tool/release.sh --allow-dirty            # ditto, ignoring uncommitted changes
#   tool/release.sh --notes-file notes.md    # attach release notes (zh text)
#   tool/release.sh --min-supported 3        # force everyone below build 3 to update
#   tool/release.sh --no-build               # only regenerate update.json from dist/
#   tool/release.sh --tag v0.2.0+2           # override the git tag in the URL
set -euo pipefail

WS="C:/Users/noaha/prj/lingueez-web"
FLUTTER="$WS/flutter"
cd "$FLUTTER"

REPO="noahal1/Lexumo"
NOTES_FILE=""
MIN_SUPPORTED=""
TAG=""
ALLOW_DIRTY=0
BUILD=1

while [ $# -gt 0 ]; do
  case "$1" in
    --allow-dirty) ALLOW_DIRTY=1; shift ;;
    --no-build) BUILD=0; shift ;;
    --notes-file) NOTES_FILE="$2"; shift 2 ;;
    --min-supported) MIN_SUPPORTED="$2"; shift 2 ;;
    --tag) TAG="$2"; shift 2 ;;
    -h|--help) sed -n '2,30p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

die() { echo "release: $*" >&2; exit 1; }

# ---------------------------------------------------------------- version ----
# `0.2.0+2` — the part before `+` is the versionName users see, the part after
# is the versionCode Android compares. Both are required: an APK with a higher
# versionName but the same code is not an update.
PUBSPEC_VERSION=$(grep -E '^version:' pubspec.yaml | head -1 | sed 's/^version:[[:space:]]*//' | tr -d '\r')
[ -n "$PUBSPEC_VERSION" ] || die "no 'version:' line in pubspec.yaml"

VERSION_NAME="${PUBSPEC_VERSION%%+*}"
if [ "$VERSION_NAME" = "$PUBSPEC_VERSION" ]; then
  die "pubspec.yaml version '$PUBSPEC_VERSION' has no build number; write it as '$PUBSPEC_VERSION+2'"
fi
VERSION_CODE="${PUBSPEC_VERSION#*+}"
case "$VERSION_CODE" in
  ''|*[!0-9]*) die "build number '$VERSION_CODE' is not a positive integer" ;;
esac
[ "$VERSION_CODE" -ge 1 ] || die "build number must be >= 1"

TAG="${TAG:-v${VERSION_NAME}+${VERSION_CODE}}"

echo "release: version $VERSION_NAME (build $VERSION_CODE), tag $TAG"

# ------------------------------------------------------------------- gates ----
if [ "$ALLOW_DIRTY" -eq 0 ]; then
  if [ -n "$(git -C "$WS" status --porcelain -- flutter 2>/dev/null)" ]; then
    die "working tree has changes under flutter/. Commit them, or pass --allow-dirty for a throwaway build."
  fi
fi

if [ ! -f android/key.properties ]; then
  if [ "$BUILD" -eq 1 ]; then
    cat >&2 <<'EOF'
release: android/key.properties is missing.

  A release signed with the debug key cannot update any installed copy:
  Android rejects an APK whose signature differs, so every user who installs
  this build would have to uninstall first. Generate a release key once, keep
  it out of git, and keep it forever:

    keytool -genkeypair -v -keystore android/upload-keystore.jks \
      -storetype JKS -keyalg RSA -keysize 2048 -validity 10000 -alias upload

  then create flutter/android/key.properties with:

    storeFile=upload-keystore.jks
    storePassword=<the password you chose>
    keyAlias=upload
    keyPassword=<the same password>

EOF
    exit 1
  fi
  echo "release: warning: android/key.properties is missing, so dist/ holds a debug-signed APK;" >&2
  echo "release:          it cannot be installed over any release-signed copy." >&2
fi

# Gradle reads the version from local.properties, not from pubspec.yaml.
# `flutter build apk` normally writes these three lines; this script builds with
# Gradle directly, so it has to do the same job. Written before the build and
# never committed (`android/.gitignore` covers local.properties).
write_local_props() {
  local props="android/local.properties"
  touch "$props"
  # Replace or append each key, leaving sdk.dir / flutter.sdk alone.
  for pair in "flutter.versionName=$VERSION_NAME" "flutter.versionCode=$VERSION_CODE" "flutter.buildMode=release"; do
    local key="${pair%%=*}"
    if grep -qE "^${key}=" "$props"; then
      # `sed -i` differs between MSYS and GNU; write through a temp file.
      grep -vE "^${key}=" "$props" > "$props.tmp"
      printf '%s\n' "$pair" >> "$props.tmp"
      mv "$props.tmp" "$props"
    else
      printf '%s\n' "$pair" >> "$props"
    fi
  done
}
write_local_props

echo "release: android/local.properties -> $VERSION_NAME ($VERSION_CODE), release mode"

# ------------------------------------------------------------------- build ----
APK="dist/lexumo-android-release.apk"

if [ "$BUILD" -eq 1 ]; then
  # The version is compiled in as well as stamped into the manifest, so a build
  # can report its own number even where the platform channel is missing (a
  # desktop `flutter run`, the Windows build).
  DEFINES=$(node -e '
    const parts = [
      `LEXUMO_VERSION=${process.argv[1]}`,
      `LEXUMO_BUILD=${process.argv[2]}`,
    ];
    process.stdout.write(parts.map((p) => Buffer.from(p, "utf8").toString("base64")).join(","));
  ' "$VERSION_NAME" "$VERSION_CODE")

  echo "release: building (this takes a few minutes)"
  # Forwarded to Gradle by build_apk.sh, which is the only way to build here.
  ./tool/build_apk.sh "-Pdart-defines=$DEFINES"
else
  echo "release: --no-build, reusing $APK"
fi

[ -f "$APK" ] || die "$APK was not produced"

# ------------------------------------------------------------------ manifest --
# Computed from the file on disk, after it exists, so the digest and size can
# never describe an older build.
SIZE=$(stat -c%s "$APK")
SHA=$(sha256sum "$APK" | cut -d' ' -f1)
URL="https://github.com/${REPO}/releases/download/${TAG}/lexumo-${VERSION_NAME}-${VERSION_CODE}.apk"

echo "release: apk $APK"
echo "release:       $SIZE bytes"
echo "release:       sha256 $SHA"

if [ -n "$NOTES_FILE" ]; then
  [ -f "$NOTES_FILE" ] || die "notes file not found: $NOTES_FILE"
  NOTES_JSON=$(
    node -e '
      const fs = require("fs");
      const raw = fs.readFileSync(process.argv[1], "utf8");
      let notes = {};
      try {
        const parsed = JSON.parse(raw);
        if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
          // { "zh": "…", "en": "…" } — already the manifest shape.
          notes = parsed;
        }
      } catch (_) {
        // Not JSON: one body of text, filed under Chinese, which is the
        // reference locale.
      }
      if (Object.keys(notes).length === 0) notes = { zh: raw.trim() };
      const clean = {};
      for (const [k, v] of Object.entries(notes)) {
        if (typeof v === "string" && v.trim()) clean[k] = v.trim();
      }
      process.stdout.write(JSON.stringify(clean));
    ' "$NOTES_FILE"
  )
else
  NOTES_JSON='{}'
fi

MANIFEST=$(node -e '
  const [version, build, url, size, sha, notes, minSupported] = process.argv.slice(1);
  const out = {
    version,
    build: Number(build),
    published: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
    apk: { url, size: Number(size), sha256: sha },
  };
  const parsedNotes = JSON.parse(notes);
  if (Object.keys(parsedNotes).length > 0) out.notes = parsedNotes;
  if (minSupported) out.minSupportedBuild = Number(minSupported);
  process.stdout.write(JSON.stringify(out, null, 2) + "\n");
' "$VERSION_NAME" "$VERSION_CODE" "$URL" "$SIZE" "$SHA" "$NOTES_JSON" "$MIN_SUPPORTED")

mkdir -p dist
printf '%s' "$MANIFEST" > dist/update.json

echo "release: wrote dist/update.json"
echo
cat dist/update.json
echo
cat <<EOF

Next (the network steps are deliberately not automated here):

  1. Upload both files to a GitHub release named for the tag:

       gh release create $TAG \\
         dist/lexumo-android-release.apk#lexumo-${VERSION_NAME}-${VERSION_CODE}.apk \\
         dist/update.json \\
         --title "$VERSION_NAME ($VERSION_CODE)" \\
         --notes-file <the notes you just used>

     The asset order matters only for the name: the manifest's URL points at
     lexumo-${VERSION_NAME}-${VERSION_CODE}.apk, so upload it under exactly that
     name (the \`#name\` suffix above renames it on upload).

  2. Keep android/upload-keystore.jks and its passwords forever. Losing it means
     no installed copy can ever be updated again.

  3. The first release a user installs by hand; every later one arrives through
     Settings -> 更新 once the manifest names a higher build number.
EOF
